import csv, re, zipfile, xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation
from pathlib import Path

xlsx = Path('/home/user/Export_Calc_to_CSV.xlsx')
out = xlsx.with_suffix('.csv')
ns = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'pkgrel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

def col_to_idx(cell_ref):
    letters = re.match(r'([A-Z]+)', cell_ref).group(1)
    n = 0
    for ch in letters:
        n = n * 26 + ord(ch) - 64
    return n - 1

def displayed_number(text):
    try:
        d = Decimal(text)
    except InvalidOperation:
        return text
    if d == d.to_integral_value():
        return str(d.quantize(Decimal(1)))
    return format(d.normalize(), 'f')

with zipfile.ZipFile(xlsx) as z:
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('main:si', ns):
            shared.append(''.join(t.text or '' for t in si.findall('.//main:t', ns)))

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    view = wb.find('main:bookViews/main:workbookView', ns)
    active_idx = int(view.attrib.get('activeTab', '0')) if view is not None else 0
    sheet = wb.findall('main:sheets/main:sheet', ns)[active_idx]
    rel_id = sheet.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    target = next(rel.attrib['Target'] for rel in rels.findall('pkgrel:Relationship', ns) if rel.attrib['Id'] == rel_id)
    sheet_path = 'xl/' + target.lstrip('/') if not target.startswith('xl/') else target

    ws = ET.fromstring(z.read(sheet_path))
    rows = []
    for row_el in ws.findall('main:sheetData/main:row', ns):
        vals = {}
        for c in row_el.findall('main:c', ns):
            ref = c.attrib.get('r')
            if not ref:
                continue
            idx = col_to_idx(ref)
            typ = c.attrib.get('t')
            value = ''
            if typ == 'inlineStr':
                value = ''.join(t.text or '' for t in c.findall('.//main:t', ns))
            else:
                v = c.find('main:v', ns)
                if v is not None and v.text is not None:
                    value = shared[int(v.text)] if typ == 's' else displayed_number(v.text)
            vals[idx] = value
        rows.append(vals)

    while rows and not rows[-1]:
        rows.pop()
    max_col = max((max(vals) + 1 for vals in rows if vals), default=0)

with out.open('w', newline='', encoding='utf-8') as f:
    writer = csv.writer(f)
    for vals in rows:
        writer.writerow([vals.get(i, '') for i in range(max_col)])

print(str(out))
print(out.read_text(encoding='utf-8'))
